SELECT p.gender, CASE WHEN p.anchor_age BETWEEN 64 AND 74 THEN o.outcome END AS outcome, s.stay_id, s.length_of_stay, cume_dist() OVER (PARTITION BY p.gender ORDER BY s.length_of_stay) AS cumulative_distribution FROM physionet-data.mimiciv_3_1_hosp.patients p JOIN physionet-data.mimiciv_3_1_hosp.admissions a ON p.subject_id = a.subject_id JOIN physionet-data.mimiciv_3_1_hosp.stays s ON a.stay_id = s.stay_id JOIN physionet-data.mimiciv_3_1_hosp.outcomes o ON a.hadm_id = o.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 64 AND 74;